#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_postorder_display_non_empty_tree(void) {
    node* root = NULL;
    int values[] = {10, 5, 15, 3, 7, 12, 18};
    int size = sizeof(values) / sizeof(values[0]);

    for (int i = 0; i < size; i++) {
        insert_bt(&root, values[i]);
    }

    // Simple stdout capture using freopen to temporary file
    FILE* original_stdout = stdout;
    FILE* temp_file = tmpfile();
    if (temp_file) stdout = temp_file;

    postorder_display(root);

    // Restore stdout and read captured output
    stdout = original_stdout;
    char output[1024] = {0};
    if (temp_file) {
        rewind(temp_file);
        fgets(output, sizeof(output), temp_file);
        fclose(temp_file);
    }

    TEST_ASSERT_NOT_EQUAL_STRING("", output);

    helper_free_tree(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_postorder_display_non_empty_tree);
    return UNITY_END();
}

